load /afs/efda-itm.eu/imp5/user/peysson/LUKE_ITM/trunk/Project_DKE/Database/PATH_files/PATH_LOCAL.mat
%
[dkepath] = load_structures_yp('dkepath','','');
%
time_interp = 1;
run_out  =  run;%everything is in run_out
occurrence_out=$occurrence_waves_out;
%
CPOs = {'equilibrium','coreprof','antennas'};
%
CPO_occurences = [occurrence_eq,occurrence_cp,occurrence_an];
