end
%
waves = itm_starwars(dkepath,shot,run,run_out,timeslice,time_interp,CPOs,CPO_occurences,remotename,iter,occurrence_out);%
output='ok';
outputdata=waves.coherentwave(1).profiles_1d.powd_tot;
